import * as Cesium from 'cesium';
import { buildDossier, composeBrief } from './enrichment.js';
import {
  INTEL_LAYERS,
  toIntelObject,
  buildTriage,
  nearestHit,
  nearbyObjects,
  insideArea,
  distanceKm,
} from './objects.js';
import {
  KIND_LABEL,
  SEV_LABEL,
  ACCENT,
  AOI_KM,
  esc,
  chip,
  ICON,
  hudHeader,
  hudCard,
  hudActions,
  sheetDrawer,
} from './markup.js';
import { runAction } from './actions.js';
import {
  blockCsv,
  objectIdentity,
  objectLineage,
  overviewSheet,
} from './sheets.js';
import { buildHud, MAX_CARDS } from './hud.js';
import { buildPlaceHud } from './place.js';
import { buildCameraHud, CAMERA_FRAME_REFRESH_MS } from './camera.js';
import { registerCctvFocusRequestListener } from '../cctvFocusRequest.js';
import { resolveAssetType } from './assetTypes.js';
import { createReferenceImages } from './referenceImages.js';
import { reticleSprite } from '../tour/pulseGraphics.js';
import { createNarrator } from '../tour/narrator.js';
import { createSubjectVisual } from './subjectVisual.js';
import {
  holdContinuousRender,
  releaseContinuousRender,
} from '../renderGovernor.js';
import { assignLanes, orthogonalPath } from './leaderRoute.js';
import { attachCctvVideo } from '../layers/cctv/videoPlayback.js';

/**
 * Live-mode intelligence view — the Constellation HUD. Click any aircraft,
 * ship, satellite or quake (or let the Director focus one): a header names
 * it, its (up to four) data sections sit in two glass sheets at the bottom
 * left and right, joined to the asset by leader lines, and analyst
 * actions run along the bottom between them. Nothing
 * scrolls. Real feed values are tagged FEED; illustrative content SIMULATED.
 */
const CACHE_MS = 4000;

function el(tag, cls, html) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (html != null) n.textContent = html;
  return n;
}

/** Safely set the HTML content of a node via DOMParser (avoids raw innerHTML). */
function setContent(node, html) {
  if (!html) { node.replaceChildren(); return; }
  const doc = new DOMParser().parseFromString(
    `<!doctype html><body>${html}`,
    'text/html',
  );
  node.replaceChildren(...doc.body.childNodes);
}

export function installIntel({
  viewer,
  dataManager,
  isLive = () => true,
  onManualFocus = () => {},
}) {
  const scene = viewer.scene;
  const narrator = createNarrator();

  // ── Console (three glass pieces around a clear centre) ───────────────
  const view = el('div', 'gev-hud');
  view.hidden = true;
  // A type photo that fails to load is removed, leaving the class outline.
  view.addEventListener(
    'error',
    (event) => {
      if (
        event.target?.tagName === 'IMG' &&
        event.target.closest('.gev-hud__ref')
      )
        event.target.remove();
    },
    true,
  );
  const header = el('div', 'gev-hud__header');
  // The title block is re-rendered; the Director's sensor tag sits beside
  // it and is set by tour/sensorLook.js (textContent only).
  const headerBody = el('div', 'gev-hud__titleblock');
  const sensorTag = el('p', 'gev-hud__sensor');
  sensorTag.hidden = true;
  header.append(headerBody, sensorTag);
  // Two data sheets, bottom left and bottom right (Pierre, 21 Oct: four
  // corner cards were too much). The HUD's sections (up to four) are split
  // between them, the first half on the left.
  const SIDES = ['l', 'r'];
  const panels = SIDES.map((side) =>
    el('section', `gev-hud__card gev-hud__card--${side} gev-glass`),
  );
  const cards = Array.from({ length: MAX_CARDS }, (_, i) =>
    el('div', `gev-hud__part gev-hud__part--${i + 1}`),
  );
  /** Put the visible sections in their sheets (first half left). */
  function assignParts() {
    const shown = cards.filter((c) => !c.hidden);
    const leftCount = Math.ceil(shown.length / 2);
    let moved = false;
    cards.forEach((node) => {
      const i = shown.indexOf(node);
      const home = i === -1 ? panels[0] : i < leftCount ? panels[0] : panels[1];
      // Keep the sections in order inside each sheet.
      if (node.parentElement !== home) {
        home.append(node);
        moved = true;
      }
    });
    for (const panel of panels) {
      const parts = [...panel.children].sort(
        (a, b) => cards.indexOf(a) - cards.indexOf(b),
      );
      if (parts.some((n, i) => panel.children[i] !== n)) {
        panel.append(...parts);
        moved = true;
      }
      const visible = parts.filter((n) => !n.hidden);
      panel.hidden = visible.length === 0;
      const sources = new Set(visible.map((n) => n.dataset.source || 'feed'));
      panel.dataset.source =
        sources.size === 1 ? [...sources][0] : sources.size ? 'mixed' : '';
    }
    return moved;
  }
  const bottom = el('div', 'gev-hud__bottom');
  const brief = el('p', 'gev-iv__brief gev-glass');
  brief.hidden = true;
  const actions = el('nav', 'gev-iv__actions gev-glass');
  actions.setAttribute('aria-label', 'Analyst actions');
  // Analyst sheets: a drawer on the right so the asset stays in view.
  const drawer = el('aside', 'gev-sheet gev-glass');
  // Panels slide in and out instead of popping (Pierre, 20 Oct).
  const reduceMotion = () =>
    globalThis.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches ===
    true;
  const HUD_LEAVE_MS = 240;
  const DRAWER_LEAVE_MS = 200;
  let hudLeaveTimer = 0;
  let drawerLeaveTimer = 0;
  /** Show the asset view, its cards sliding in from their sides. */
  function enterHud() {
    clearTimeout(hudLeaveTimer);
    view.classList.remove('is-leaving', 'is-entering');
    view.hidden = false;
    if (reduceMotion()) return;
    void view.offsetWidth; // restart the entrance animation
    view.classList.add('is-entering');
  }
  /** Hide the asset view, its cards sliding out first. */
  function leaveHud() {
    clearTimeout(hudLeaveTimer);
    view.classList.remove('is-entering');
    if (view.hidden || reduceMotion()) {
      view.hidden = true;
      view.classList.remove('is-leaving');
      return;
    }
    view.classList.add('is-leaving');
    hudLeaveTimer = setTimeout(() => {
      view.hidden = true;
      view.classList.remove('is-leaving');
    }, HUD_LEAVE_MS);
  }
  function openDrawer() {
    clearTimeout(drawerLeaveTimer);
    drawer.classList.remove('is-leaving');
    drawer.hidden = false;
  }
  /** Close the sheets drawer, sliding it out, then clear it. */
  function closeDrawer(done) {
    clearTimeout(drawerLeaveTimer);
    const finish = () => {
      drawer.hidden = true;
      drawer.classList.remove('is-leaving');
      drawer.replaceChildren();
      done?.();
    };
    if (drawer.hidden || reduceMotion()) return finish();
    drawer.classList.add('is-leaving');
    drawerLeaveTimer = setTimeout(finish, DRAWER_LEAVE_MS);
  }
  drawer.setAttribute('aria-label', 'Analyst sheets');
  drawer.hidden = true;
  bottom.append(brief, actions);
  // Leader lines from the asset to each card (decorative).
  const svgNS = 'http://www.w3.org/2000/svg';
  const leaders = document.createElementNS(svgNS, 'svg');
  leaders.setAttribute('class', 'gev-hud__leaders');
  leaders.setAttribute('aria-hidden', 'true');
  leaders.setAttribute('shape-rendering', 'geometricPrecision');
  const defs = document.createElementNS(svgNS, 'defs');
  leaders.append(defs);
  // Per leader: a soft halo, the line itself (fading in from the asset), a
  // light-blue data pulse travelling asset → card, and an end dot that
  // brightens as each pulse arrives. Pulses are staggered per card.
  const mk = (tag, attrs) => {
    const n = document.createElementNS(svgNS, tag);
    for (const [k, v] of Object.entries(attrs)) n.setAttribute(k, v);
    return n;
  };
  const leaderEls = panels.map((_, i) => {
    const gradId = `gev-lead-grad-${i}`;
    const grad = mk('linearGradient', {
      id: gradId,
      gradientUnits: 'userSpaceOnUse',
    });
    const stopA = mk('stop', { offset: '0', 'stop-opacity': '0.1' });
    const stopB = mk('stop', { offset: '1', 'stop-opacity': '0.6' });
    grad.append(stopA, stopB);
    defs.append(grad);
    const g = mk('g', { style: `--gev-delay:${(i * 0.65).toFixed(2)}s` });
    const halo = mk('path', { class: 'gev-lead__halo' });
    const line = mk('path', {
      class: 'gev-lead__line',
      stroke: `url(#${gradId})`,
    });
    const pulse = mk('path', { class: 'gev-lead__pulse', pathLength: '100' });
    const dot = mk('circle', { class: 'gev-lead__dot', r: '2.25' });
    g.append(halo, line, pulse, dot);
    leaders.append(g);
    return { g, grad, stopA, stopB, halo, line, pulse, dot };
  });
  const toast = el('div', 'gev-hud__toast gev-glass');
  toast.setAttribute('role', 'status');
  toast.hidden = true;
  // When the drawer (or alert) takes the right column, both sheets stack
  // in one scrolling column on the left instead of one of them hiding.
  const stack = el('div', 'gev-hud__cards');
  for (const c of cards) panels[0].append(c);
  view.append(leaders, header, ...panels, stack, bottom, drawer);
  const narrow = window.matchMedia?.('(max-width: 900px)');
  function placeCards() {
    const stacked =
      !narrow?.matches &&
      (['sheets', 'alert'].includes(document.body.dataset.gevRight || '') ||
        document.body.dataset.gevLeft === 'layers');
    if (stacked === (panels[0].parentElement === stack)) return;
    if (stacked) stack.append(...panels);
    else for (const p of panels) view.insertBefore(p, stack);
    measureCards?.();
  }
  const placeObserver = new MutationObserver(placeCards);
  placeObserver.observe(document.body, {
    attributes: true,
    attributeFilter: ['data-gev-right', 'data-gev-left'],
  });

  // Camera video: one persistent <video> per slot (card / large view), moved
  // into each re-rendered placeholder so refreshes never restart playback.
  const players = new Map(); // slot -> HTMLVideoElement
  const streams = new Map(); // slot -> live-stream playback (hls)
  const failedStreams = new Set(); // stream URLs that fell back to stills
  function stillFallback(fig) {
    const poster = fig.dataset.poster;
    fig.removeAttribute('data-video');
    fig.querySelector('video')?.remove();
    if (poster && !fig.querySelector('img')) {
      const img = document.createElement('img');
      img.src = poster;
      img.alt = fig.getAttribute('aria-label') || '';
      img.decoding = 'async';
      fig.prepend(img);
    }
    const badge = fig.querySelector('.gev-hud__live');
    if (badge) badge.textContent = 'LIVE STILL';
  }
  function mountVideos(root) {
    for (const fig of root.querySelectorAll('[data-video]')) {
      const slot = fig.dataset.videoSlot || 'card';
      const src = fig.dataset.video;
      const live = fig.dataset.videoType === 'hls';
      if (live && failedStreams.has(src)) {
        stillFallback(fig);
        continue;
      }
      let v = players.get(slot);
      if (!v) {
        v = document.createElement('video');
        v.muted = true;
        v.autoplay = true;
        v.playsInline = true;
        v.setAttribute('playsinline', '');
        players.set(slot, v);
      }
      v.setAttribute('aria-label', fig.getAttribute('aria-label') || '');
      if (v.dataset.src !== src) {
        streams.get(slot)?.dispose();
        streams.delete(slot);
        v.dataset.src = src;
        if (fig.dataset.poster) v.poster = fig.dataset.poster;
        if (live) {
          // Live stream through the server relay; hls.js loads on demand.
          const playback = attachCctvVideo(v, src, 'hls', {
            onFailure: () => {
              failedStreams.add(src);
              streams.delete(slot);
              delete v.dataset.src;
              for (const f of document.querySelectorAll(
                `[data-video-slot="${slot}"][data-video]`,
              ))
                if (f.dataset.video === src) stillFallback(f);
            },
          });
          streams.set(slot, playback);
        } else {
          v.loop = true;
          v.src = src;
        }
      }
      fig.prepend(v);
      v.play?.().catch(() => {});
    }
  }
  function stopVideos() {
    for (const playback of streams.values()) playback.dispose();
    streams.clear();
    for (const v of players.values()) {
      v.pause();
      v.removeAttribute('src');
      delete v.dataset.src;
      v.load();
      v.remove();
    }
    players.clear();
  }
  document.body.append(toast);

  const triage = el('section', 'gev-triage gev-glass');
  triage.setAttribute('aria-label', 'Triage queue');
  triage.hidden = true;
  document.body.append(view, triage);

  // ── Globe graphics: reticle + areas of interest ──────────────────────
  const marker = viewer.entities.add({
    show: false,
    position: Cesium.Cartesian3.fromDegrees(0, 0),
    billboard: {
      image: reticleSprite(ACCENT),
      width: 46,
      height: 46,
      disableDepthTestDistance: Number.POSITIVE_INFINITY,
    },
  });
  const areas = []; // { key, title, lat, lon, radiusKm, entity }
  const watchlist = new Map(); // key -> object snapshot

  // ── Data (cached so clicks and the badge never rescan every layer) ───
  let cache = { at: 0, objects: [] };
  function layerOn(id) {
    try {
      return dataManager.isEnabled(id) === true;
    } catch {
      return false;
    }
  }
  function layerModule(id) {
    try {
      return dataManager.layers.get(id)?.module || null;
    } catch {
      return null;
    }
  }
  function collect({ fresh = false } = {}) {
    const now = performance.now();
    if (!fresh && now - cache.at < CACHE_MS) return cache.objects;
    const out = [];
    for (const id of Object.keys(INTEL_LAYERS)) {
      if (!layerOn(id)) continue;
      let records = [];
      try {
        records = layerModule(id)?.getAnalystRecords?.(20000) || [];
      } catch (error) {
        console.warn(`[intel] ${id} records unavailable`, error);
      }
      for (const r of records) {
        const o = toIntelObject(id, r);
        if (o) out.push(o);
      }
    }
    cache = { at: now, objects: out };
    return out;
  }
  const cartesianOf = (o) =>
    Cesium.Cartesian3.fromDegrees(o.lon, o.lat, o.heightM || 0);

  // ── Selection state ──────────────────────────────────────────────────
  let selected = null;
  let state = {};
  let nearby = { total: 0, radiusKm: 0, items: [] };
  let followTimer = null;

  function placeMarker(o) {
    // Aircraft and satellites use their layer's own smooth follow camera and
    // highlight; the reticle marks ships and quakes.
    marker.show = o.kind === 'vessel' || o.kind === 'earthquake';
    scene.requestRender();
  }
  let hud = null;
  let headline = '';
  const touring = () => document.body.classList.contains('gev-touring');
  function renderActions() {
    if (!hud) return;
    // A place has no analyst actions (watching a place is not a thing yet).
    setContent(
      actions,
      selected?.kind === 'place'
        ? ''
        : hudActions(hud, state, { touring: touring() }),
    );
  }
  // Only touch the DOM when a card's markup actually changed: rebuilding it
  // every refresh re-lays out the page and would reload the type photo.
  const lastHtml = new WeakMap();
  function setHtml(node, html) {
    if (lastHtml.get(node) === html) return false;
    lastHtml.set(node, html);
    setContent(node, html);
    return true;
  }
  // ── Places (Director airport and city stops) ─────────────────────────
  // Weather per station, fetched once per 10 minutes and re-rendered when it
  // arrives; the counts and incidents refresh from the live layers.
  const metars = new Map(); // station → { report, at } | 'loading'
  function metarFor(icao) {
    if (!icao) return null;
    const hit = metars.get(icao);
    if (hit === 'loading') return 'loading';
    if (hit && Date.now() - hit.at < 10 * 60_000) return hit.report;
    metars.set(icao, 'loading');
    fetch(`/api/metar?ids=${encodeURIComponent(icao)}`, {
      headers: { Accept: 'application/json' },
    })
      .then((r) => (r.ok ? r.json() : null))
      .then((body) => {
        metars.set(icao, {
          report: body?.reports?.[0] || null,
          at: Date.now(),
        });
      })
      .catch(() => metars.set(icao, { report: null, at: Date.now() }))
      .finally(() => {
        if (selected?.kind === 'place') render();
      });
    return 'loading';
  }
  /** Nearest street camera within 10 km of a place, with its current still. */
  function nearestCamera(place) {
    const cams = layerOn('cctv') ? layerModule('cctv') : null;
    let best = null;
    for (const record of cams?.getAnalystRecords?.() || []) {
      const km = distanceKm(
        { lat: place.lat, lon: place.lon, heightM: 0 },
        { lat: record.lat, lon: record.lon, heightM: 0 },
      );
      if (km <= 10 && (!best || km < best.km)) best = { record, km };
    }
    return best ? { ...best, frameUrl: cams.frameUrl?.(best.record.id) } : null;
  }

  function placeContext(o) {
    const objects = collect();
    const of = (layerId) => objects.filter((x) => x.layerId === layerId);
    const plain = (id) => {
      try {
        return layerOn(id)
          ? layerModule(id)?.getAnalystRecords?.(5000) || []
          : [];
      } catch {
        return [];
      }
    };
    // Aircraft loaded ahead by the Director count until the live layer
    // covers the place (they never replace a live record).
    let flights = of('flights');
    const staged = Date.now() - (o.stagedAt || 0) < 60_000 ? o.staged : [];
    if (staged?.length) {
      const seen = new Set(flights.map((f) => f.icao24).filter(Boolean));
      flights = [...flights, ...staged.filter((f) => !seen.has(f.icao24))];
    }
    return {
      flights,
      military: of('military'),
      vessels: of('ais-live-vessels'),
      satellites: of('satellites'),
      quakes: of('earthquakes'),
      fires: plain('local-firms'),
      storms: plain('weather-cyclones'),
      metar: metarFor(o.place.icao),
      camera: nearestCamera(o.place),
      layersOn: {
        flights: layerOn('flights'),
        military: layerOn('military'),
        vessels: layerOn('ais-live-vessels'),
        satellites: layerOn('satellites'),
        earthquakes: layerOn('earthquakes'),
        fires: layerOn('local-firms'),
        storms: layerOn('weather-cyclones'),
      },
    };
  }

  function render() {
    if (!selected) return;
    if (selected.kind === 'place')
      hud = buildPlaceHud(selected.place, placeContext(selected));
    else if (selected.kind === 'camera') {
      const cams = layerModule('cctv');
      const all = nearbyObjects(collect(), selected, { limit: Infinity });
      hud = buildCameraHud(selected, {
        frameUrl: cams?.frameUrl?.(selected.id) || null,
        frameGenuine: cams?.frameIsGenuine?.(selected.id) ?? true,
        mediaUrl: cams?.mediaUrl?.(selected.id) || null,
        mediaType: cams?.mediaType?.(selected.id) || null,
        refreshedAt: Date.now(),
        nearby: all.items,
        radiusKm: all.radiusKm,
        panel3d: cams?.getActiveCameraId?.() === selected.id,
        adjusting: !!cams?.getParams?.().calibrationMode,
      });
    } else {
      const all = nearbyObjects(collect(), selected, { limit: Infinity });
      hud = buildHud(selected, all.items);
    }
    setHtml(headerBody, hudHeader(hud, headline));
    let changed = false;
    cards.forEach((node, i) => {
      const c = hud.cards[i];
      if (node.hidden !== !c) {
        node.hidden = !c;
        changed = true;
      }
      node.dataset.source = c?.source || '';
